#include "session.hpp"
#include "garage_upgrades.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace perekup;Json cities={{"home",{{"id","home"}}}},cars=Json::object();for(int i=1;i<=6;++i)cars[std::to_string(i)]={{"id",i}};auto root=fs::temp_directory_path()/("perekup-upgrade-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{{Session s(root,cities,cars,"home");s.create("Игрок","TEST",1000000);auto d=s.state;d["balance"]=1000000;Transport t(cities,cars,"home");for(int i=1;i<=6;++i){d["garage"].push_back(i);t.garage=d["garage"];t.park(i,"home",1000000);}d["transport"]=t.state;s.commit(d);assert(buyNativeGarage(d,1,cities,cars,"home",[&](const Json& v){s.commit(v);}));assert(d["balance"]==700000&&d["garageCapacity"]==5);int parked=0;for(const auto& v:d["transport"]["vehicles"])parked+=v["place"]=="garage";assert(parked==5&&d["garage"].size()==6);auto before=d;assert(!buyNativeGarage(d,1,cities,cars,"home",[](const Json&){}));assert(!buyNativeGarage(d,2,cities,cars,"home",[](const Json&){}));assert(d==before);d["balance"]=1000000;before=d;bool failed=false;try{buyNativeGarage(d,2,cities,cars,"home",[](const Json&){throw std::runtime_error("Disk full");});}catch(...){failed=true;}assert(failed&&d==before);assert(buyNativeGarage(d,2,cities,cars,"home",[&](const Json& v){s.commit(v);}));}{Session s(root,cities,cars,"home");assert(s.load().status==LoadStatus::Loaded);assert(nativeGarageLevel(s.state)==2&&s.state["garageCapacity"]==8&&s.state["balance"]==200000);assert(s.state["bank"]["entries"][0]["kind"]=="expense");}fs::remove_all(root);std::cout<<"PASS sequential garage purchase, exact price, ledger, rebalance, no duplicate charge, rollback and reload\n";}catch(...){fs::remove_all(root);throw;}}
